def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3

    if count == 0:
        return None

    total = v1 + v2 + v3
    average = total / count

    return {
        "value": average,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "count": count,
            "total": total,
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
